const m = $json.message || $json.edited_message || {};
const chat_id = String(m.chat?.id ?? '');
const first_name = m.from?.first_name || 'Athlete';
const text = String(m.text || m.caption || '').trim();
const lang_hint = String(m.from?.language_code || '').startsWith('fr') ? 'fr' : 'en';
const photo = Array.isArray(m.photo) && m.photo.length ? m.photo[m.photo.length - 1].file_id : null;
let command = 'chat', args = text;
if (m.location) { command = 'eat'; args = ''; }
else if (photo) { command = 'photo'; args = text; }
else if (text.startsWith('/')) {
  const [c, ...rest] = text.split(/\s+/);
  command = c.slice(1).split('@')[0].toLowerCase();
  args = rest.join(' ').trim();
}
else if (/^\d{8,14}$/.test(text)) { command = 'scan'; args = text; }
const alias = { profil: 'profile', setup: 'profile', me: 'profile', cuisine: 'cook', fridge: 'cook', frigo: 'cook', barcode: 'scan', muscles: 'muscle', exercise: 'muscle', exercises: 'muscle' };
command = alias[command] || command;
const known = ['start', 'help', 'profile', 'link', 'today', 'workout', 'muscle', 'eat', 'cook', 'scan', 'photo', 'done', 'log', 'report', 'stop', 'chat'];
if (!known.includes(command)) command = 'help';
const is_start = command === 'start';
if (is_start) command = 'help';
return [{ json: { chat_id, first_name, text, command, args, is_start, photo_file_id: photo, lang_hint,
  lat: m.location?.latitude ?? null, lon: m.location?.longitude ?? null } }];

// Every Telegram user is a member: no website account needed.
// A GymBuddy API user is created from the Telegram profile (or recreated if the API database was reset),
// so the chatbot, workouts, restaurants, photo scanner and fridge chef are personalised for everybody.
const API = 'https://gymbuddy-api-zeta.vercel.app'.replace(/\/+$/, '');
const helpers = this.helpers;
const cmd = $('Parse Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.chat_id);
const row = rows.find(r => String(r.chat_id) === cmd.chat_id) || null;
const isNew = !row;

let profile = {};
try { profile = JSON.parse(row?.profile_json || '{}') || {}; } catch (e) { profile = {}; }
if (!profile.language) profile.language = row?.language || cmd.lang_hint;

// ---- /profile 22 m 175 72 muscle gym 3 halal allergy peanuts injury knee ----
function parseProfile(raw) {
  const p = {}, unknown = [];
  const s = ' ' + String(raw).toLowerCase().replace(/,/g, ' ') + ' ';
  const take = (re) => { const m = s.match(re); return m ? m : null; };
  let m;
  if ((m = take(/\b(\d{2,3}(?:[.,]\d)?)\s*(cm)\b/))) p.height_cm = Number(m[1].replace(',', '.'));
  if ((m = take(/\b(\d{2,3}(?:[.,]\d)?)\s*(kg|kilos?)\b/))) p.weight_kg = Number(m[1].replace(',', '.'));
  if ((m = take(/\b(\d{1,2})\s*(ans|years?|yo|y)\b/))) p.age = Number(m[1]);
  if ((m = take(/\b([1-7])\s*(d|days?|jours?|j|x|x\/week|\/week|\/sem|sessions?)\b/))) p.days_per_week = Number(m[1]);
  const bare = (s.match(/(?<![\d.,])\d{1,3}(?:[.,]\d)?(?![\d.,]*\s*(cm|kg|kilos?|ans|years?|yo|y|d|days?|jours?|j|x|sessions?)\b)/g) || []).map(x => Number(x.replace(',', '.')));
  for (const n of bare) {
    if (p.age === undefined && n >= 14 && n <= 90 && !(n >= 120)) { p.age = n; continue; }
    if (p.height_cm === undefined && n >= 120 && n <= 230) { p.height_cm = n; continue; }
    if (p.weight_kg === undefined && n >= 30 && n <= 250) { p.weight_kg = n; continue; }
    if (p.days_per_week === undefined && n >= 1 && n <= 7) { p.days_per_week = n; continue; }
  }
  if (/\b(f|female|femme|woman|girl|fille)\b/.test(s)) p.sex = 'female'; else if (/\b(m|male|homme|man|boy|garcon|garçon)\b/.test(s)) p.sex = 'male';
  if (/\b(lose|cut|fat|weight loss|perte|perdre|maigrir|seche|sèche)\b/.test(s)) p.goal = 'lose_fat';
  else if (/\b(recomp|recomposition)\b/.test(s)) p.goal = 'recomp';
  else if (/\b(maintain|maintien|maintenir)\b/.test(s)) p.goal = 'maintain';
  else if (/\b(muscle|bulk|mass|masse|gain|prise)\b/.test(s)) p.goal = 'build_muscle';
  if (/\b(bodyweight|no equipment|sans materiel|sans matériel|poids du corps|calisthenics)\b/.test(s)) p.equipment = 'bodyweight';
  else if (/\b(dumbbells?|halteres?|haltères?|home|maison)\b/.test(s)) p.equipment = 'dumbbells';
  else if (/\b(gym|salle)\b/.test(s)) p.equipment = 'gym';
  if (/\b(vegan|végan)\b/.test(s)) p.diet = 'vegan'; else if (/\b(vegetarian|végétarien|vegetarien)\b/.test(s)) p.diet = 'vegetarian'; else if (/\bhalal\b/.test(s)) p.diet = 'halal';
  if (/\b(advanced|avancé|avance)\b/.test(s)) p.experience = 'advanced'; else if (/\b(intermediate|intermédiaire|intermediaire)\b/.test(s)) p.experience = 'intermediate'; else if (/\b(beginner|débutant|debutant)\b/.test(s)) p.experience = 'beginner';
  if (/\b(sedentary|sédentaire|sedentaire)\b/.test(s)) p.activity = 'sedentary'; else if (/\b(very active|très actif|tres actif)\b/.test(s)) p.activity = 'very_active';
  if ((m = s.match(/\b(?:allerg(?:y|ies|ie|ique)?|allergic to)\s*[:=]?\s*([a-zà-ÿ ]+?)(?=\b(?:injur|bless|$)|\s{2}|$)/))) p.allergies = m[1].trim().split(/\s+(?:and|et)\s+|\s+/).filter(w => w.length > 2);
  if ((m = s.match(/\b(?:injur(?:y|ies|ed)?|blessures?|bless[ée]?)\s*[:=]?\s*([a-zà-ÿ ]+?)(?=\b(?:allerg|$)|\s{2}|$)/))) p.injuries = m[1].trim().split(/\s+(?:and|et)\s+/).map(w => w.trim()).filter(Boolean);
  if (/\b(fr|français|francais)\b/.test(s)) p.language = 'fr'; else if (/\b(en|english|anglais)\b/.test(s)) p.language = 'en';
  return { p, unknown };
}

let profileUpdated = false;
if (cmd.command === 'profile' && cmd.args) {
  const r = parseProfile(cmd.args);
  if (Object.keys(r.p).length) { Object.assign(profile, r.p); profileUpdated = true; }
}

const KEYS = ['age', 'sex', 'height_cm', 'weight_kg', 'activity', 'goal', 'experience', 'days_per_week', 'equipment', 'diet', 'allergies', 'injuries', 'language'];
const clean = {}; for (const k of KEYS) if (profile[k] !== undefined && profile[k] !== '') clean[k] = profile[k];

async function api(method, path, body) {
  try {
    return await helpers.httpRequest({ method, url: API + path, body, json: true, timeout: 20000 });
  } catch (e) { return null; }
}
let userId = row?.user_id || '';
let user = null;
if (userId && !profileUpdated) user = await api('GET', `/api/users/${encodeURIComponent(userId)}`);
if (!user) {
  user = await api('POST', '/api/users', { name: String(row?.name || cmd.first_name).slice(0, 80), profile: clean });
  if (user?.user_id) userId = user.user_id;
}
const t = user?.targets || {};
const p = user?.profile || clean;
const sub = {
  chat_id: cmd.chat_id, email: row?.email || '', user_id: userId, name: row?.name || cmd.first_name,
  calories_target: t.calories ?? row?.calories_target ?? '', protein_g: t.protein_g ?? row?.protein_g ?? '',
  carbs_g: t.carbs_g ?? row?.carbs_g ?? '', fat_g: t.fat_g ?? row?.fat_g ?? '', water_l: t.water_l ?? row?.water_l ?? '',
  language: p.language || profile.language || 'en',
  streak: row?.streak || 0, best_streak: row?.best_streak || 0, total_workouts: row?.total_workouts || 0, last_done: row?.last_done || '',
  active: (isNew || cmd.is_start || profileUpdated) ? 'yes' : (row?.active || 'yes'),
  joined_at: row?.joined_at || $now.toISO(), linked_at: row?.linked_at || '',
  profile_json: JSON.stringify(Object.fromEntries(KEYS.filter(k => p[k] !== undefined).map(k => [k, p[k]]))),
};
return [{ json: { ...cmd, linked: !!sub.email, is_new: isNew, has_profile: !!(row?.profile_json) || profileUpdated,
  profile_updated: profileUpdated, api_ok: !!user, targets: t, sub, route: cmd.command } }];

